  users,
} from "@/server/db";
import type { ImportIssuesInput } from "@/schemas/issue-import";''')
s+='''
/** The issues of a previously recorded import, in file order; null if the key is new. */
export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<{ projectId: ProjectId; issues: readonly Issue[] } | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  const ids = JSON.parse(row.issueIds) as IssueId[];
  const found: Issue[] = [];
  for (const id of ids) {
    const issue = await findIssueById(orgId, id);
    if (issue) found.push(issue);
  }
  return { projectId: row.projectId as ProjectId, issues: found };
}

/**
 * Writes a whole import atomically: labels, numbered issues, label links and
 * the import record either all land or none do.
 */
export function insertImport(
  input: ImportIssuesInput,
  authorId: UserId,
  defaultLabelColor: string,
): readonly IssueId[] {
  const stamp = toIsoTimestamp(new Date());
  return getDb().transaction((tx) => {
    const memberRows = tx
      .select({ userId: members.userId, email: users.email })
      .from(members)
      .innerJoin(users, eq(users.id, members.userId))
      .where(
        and(
          eq(members.orgId, input.orgId),
          eq(members.status, "active"),
          isNull(members.archivedAt),
        ),
      )
      .all();
    const byEmail = new Map(
      memberRows.map((m) => [m.email.toLowerCase(), m.userId]),
    );

    const labelIds = new Map(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(eq(labels.orgId, input.orgId))
        .all()
        .map((l) => [l.name, l.id]),
    );

    const max = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          eq(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let number = max?.value ?? 0;

    const ids: IssueId[] = [];
    for (const row of input.rows) {
      const rowLabelIds: string[] = [];
      for (const name of new Set(row.labels)) {
        let id = labelIds.get(name);
        if (id === undefined) {
          id = newId();
          tx.insert(labels)
            .values({
              id,
              orgId: input.orgId,
              name,
              color: defaultLabelColor,
              description: null,
              createdAt: stamp,
              updatedAt: stamp,
            })
            .run();
          labelIds.set(name, id);
        }
        rowLabelIds.push(id);
      }

      number += 1;
      const created = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId,
          assigneeId:
            row.assigneeEmail === null
              ? null
              : (byEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning({ id: issues.id })
        .get();

      if (rowLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            rowLabelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: created.id,
              labelId,
            })),
          )
          .run();
      }
      ids.push(created.id as IssueId);
    }

    tx.insert(issueImports)
      .values({
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        issueIds: JSON.stringify(ids),
        createdAt: stamp,
      })
      .run();

    return ids;
  });
}
