s=open(p).read()
s=s.replace('import { assertCan }','import { consumeRateLimit, setOrgPlan } from "@/lib/rate-limit";\nimport { assertCan }')
s=s.replace('import type { Issue, IssueBoardColumn, IssueWithRelations }','import type { ImportIssuesInput } from "@/schemas/issue-import";\nimport type {\n  Issue,\n  IssueBoardColumn,\n  IssueImportResult,\n  IssueWithRelations,\n}')
s=s.replace('export async function updateIssue(','''/** Default colour of labels created on the fly by an import. */
const IMPORT_LABEL_COLOR = "#94a3b8";

/**
 * Bulk import: same gates as `createIssue`, checked for the whole batch before
 * anything is written. A key already imported in this workspace replays the
 * first result. Publishes one `issues.imported` rather than per-issue events.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const previous = await issueRepo.findImport(input.orgId, input.importKey);
  if (previous) {
    return {
      importKey: input.importKey,
      projectId: previous.projectId,
      issues: previous.issues,
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  setOrgPlan(input.orgId, org.plan);
  const verdict = await consumeRateLimit(
    input.orgId,
    "issue:create",
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const ids = issueRepo.insertImport(input, actor.userId, IMPORT_LABEL_COLOR);
  const issues: Issue[] = [];
  for (const id of ids) {
    issues.push(
      requireFound(await issueRepo.findIssueById(input.orgId, id), "Issue", id),
    );
  }

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: ids,
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues,
    replayed: false,
  };
}

